// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        vm.assume(amount > 0);
        address nonOwner = address(0x123);
        vm.assume(nonOwner != c.owner());
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(nonOwner);
        try c.sendMoney(target, amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok && address(c).balance == balanceBefore);
    }
}
